/**
 * Test helper: build a throwaway BASH_ENV shim and run bash commands through it.
 *
 * The shim is generated by lib/shim.js exactly like the plugin does at runtime,
 * so the tests exercise the real interception path instead of calling the
 * client directly.
 */

import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { buildShim } from '../../lib/shim.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = dirname(dirname(HERE));

export const EXECUTABLE = 'C:/Windows/System32/WindowsPowerShell/v1.0/powershell.exe';
export const PIPE = 'dsh-ps51-guard-test-' + process.pid + '-' + Math.random().toString(16).slice(2, 8);

/**
 * Create a temp runtime directory plus the generated shim.
 * @param {{pwsh7?: string | null, guard?: boolean}} [options]
 * @returns {{runtime: string, shimPath: string, pipe: string, pwsh7: string | null, cleanup: () => void}}
 */
export function createRuntime({ pwsh7 = null, guard = true } = {}) {
	const runtime = mkdtempSync(join(tmpdir(), 'ps51-guard-test-'));
	const shimPath = join(runtime, 'bash-env.sh');
	const shim = buildShim({
		executable: EXECUTABLE,
		node: process.execPath,
		client: join(ROOT, 'lib', 'client.js'),
		hostScript: join(ROOT, 'host', 'ps51-host.ps1'),
		runtime,
		pipe: PIPE,
		// A unique pipe per test process keeps a stale host from an earlier run
		// (same name, old script) from answering this run's requests.
		marker: 'test',
		pwsh7,
		guard,
	});
	writeFileSync(shimPath, shim, 'utf8');
	return {
		runtime,
		shimPath,
		pipe: PIPE,
		pwsh7,
		cleanup() {
			rmSync(runtime, { recursive: true, force: true });
		},
	};
}

/**
 * Run one command through bash with the generated shim as BASH_ENV.
 * @param {string} command
 * @param {{runtime: object, env?: Record<string, string>, timeoutMs?: number}} options
 * @returns {{code: number|null, stdout: string, stderr: string}}
 */
export function runBash(command, { runtime, env = {}, timeoutMs = 120000 } = {}) {
	const child = spawnSync('bash', ['-c', command], {
		cwd: ROOT,
		env: {
			// Model a real subprocess environment: PowerShell needs PATHEXT to
			// recognise .exe files, and the host mirrors the caller's variables.
			...process.env,
			PATH: process.env.PATH ?? '',
			HOME: process.env.HOME ?? '',
			SystemRoot: process.env.SystemRoot ?? 'C:/Windows',
			TEMP: process.env.TEMP ?? tmpdir(),
			BASH_ENV: runtime.shimPath,
			PS51_PREV_BASH_ENV: '',
			PS51_RUNTIME: runtime.runtime,
			PS51_PIPE: runtime.pipe,
			PS51_PWSH7: runtime.pwsh7 ? '1' : '0',
			...env,
		},
		encoding: 'utf8',
		timeout: timeoutMs,
	});
	return {
		code: child.status,
		stdout: child.stdout ?? '',
		stderr: child.stderr ?? '',
	};
}